from pathlib import Path
p=Path('admin.html')
s=p.read_text()
marker='/* WENIK ADMIN LIGHT IDENTITY V1 */'
css='''\n/* WENIK ADMIN LIGHT IDENTITY V1 */\n:root{--w-purple:#8f24ff;--w-pink:#ef159d;--w-orange:#ff6f21;--w-yellow:#ffd21c;--w-ink:#21172c;--w-muted:#756b7d;--w-line:rgba(118,73,145,.16)}\nbody{background:radial-gradient(circle at 0 0,rgba(143,36,255,.09),transparent 27%),radial-gradient(circle at 100% 0,rgba(255,111,33,.09),transparent 25%),#fbf9fc;color:var(--w-ink)}\n.wrap{max-width:1120px}.brand{font-size:29px;background:linear-gradient(100deg,var(--w-purple),var(--w-pink) 42%,var(--w-orange) 75%,var(--w-yellow));-webkit-background-clip:text;background-clip:text;color:transparent}.sub{color:#a329b8}.hero,.card{background:rgba(255,255,255,.94);border:1px solid var(--w-line);box-shadow:0 14px 38px rgba(58,25,75,.08)}.hero:before{background:linear-gradient(90deg,var(--w-purple),var(--w-pink),var(--w-orange),var(--w-yellow))}.muted{color:var(--w-muted)}.field,select,textarea{background:#fff;color:var(--w-ink);border:1px solid var(--w-line);box-shadow:0 5px 16px rgba(58,25,75,.035)}.field::placeholder,textarea::placeholder{color:#9d95a3}.btn{color:#fff;background:linear-gradient(100deg,var(--w-purple),var(--w-pink) 42%,var(--w-orange) 76%,var(--w-yellow));box-shadow:0 9px 22px rgba(239,21,157,.13)}.btn.secondary{background:#fff;color:#6f278f;border:1px solid rgba(143,36,255,.23)}.btn.ok{background:linear-gradient(90deg,#6f35d9,var(--w-purple),var(--w-pink))}.tab{background:#fff;color:#776d7f;border:1px solid var(--w-line);box-shadow:0 4px 13px rgba(58,25,75,.035)}.tab.active{color:#fff;background:linear-gradient(100deg,var(--w-purple),var(--w-pink),var(--w-orange))}.metric{background:#fff;border:1px solid var(--w-line);box-shadow:0 7px 20px rgba(58,25,75,.05)}.pill{background:linear-gradient(100deg,rgba(143,36,255,.10),rgba(239,21,157,.10),rgba(255,111,33,.10));color:#7c268f;border:1px solid rgba(143,36,255,.13)}.status{color:#a52b75}.good{color:#14865d}.error{color:#c53858}.itemImg{border-color:var(--w-line)}\n'''
if marker not in s:
    s=s.replace('</style>',css+'\n</style>',1)
p.write_text(s)
